            <v-card class="signup-card elevation-20" :class="{ 'rtl': $i18n.locale === 'ar' }">
              <!-- شعار التطبيق -->
              <div class="text-center pt-8">
                <v-avatar size="80" class="logo-avatar mb-4">
                  <v-icon size="50" color="white">mdi-account-plus</v-icon>
