                <!-- مؤشر قوة كلمة المرور -->
                <v-slide-y-transition>
                  <v-alert v-if="passwordStrength !== 'weak' && password.length > 0" :type="passwordStrengthColor" dense
                    class="mb-4 password-strength-alert">
                    <v-row align="center" no-gutters>
                      <v-col cols="auto" class="mr-2">
                        <v-icon>{{ passwordStrengthIcon }}</v-icon>
                      </v-col>
                      <v-col>
                        {{ $t(`signup.passwordStrength.${passwordStrength}`) }}
                      </v-col>
                    </v-row>
                  </v-alert>
