                <!-- نموذج إنشاء الحساب -->
                <v-form>
                  <!-- اسم المستخدم -->
                  <v-text-field v-model="name" :label="$t('signup.name')" :rules="nameRules"
                    :error-messages="nameErrors" name="name" prepend-inner-icon="mdi-account-outline" type="text"
                    required outlined dense class="mb-2" @input="$v.name.$touch()" @blur="$v.name.$touch()"
                    :loading="loading" :counter="20" autocomplete="name">
                    <template v-slot:counter="{ value }">
                      <span :class="{ 'error--text': value.length > 20 }">
                        {{ value.length }}/20
                      </span>
                    </template>
                  </v-text-field>

                  <!-- البريد الإلكتروني -->
                  <v-text-field v-model="email" :label="$t('signup.email')" :rules="emailRules"
                    :error-messages="emailErrors" name="email" prepend-inner-icon="mdi-email-outline" type="email"
                    required outlined dense class="mb-2" @input="$v.email.$touch()" @blur="$v.email.$touch()"
                    :loading="loading" autocomplete="email"></v-text-field>

                  <!-- كلمة المرور -->
                  <v-text-field v-model="password" :label="$t('signup.password')" :rules="passwordRules"
                    :error-messages="passwordErrors" name="password"
                    :prepend-inner-icon="showPassword ? 'mdi-lock-open' : 'mdi-lock'"
                    :append-icon="showPassword ? 'mdi-eye-off' : 'mdi-eye'" @click:append="showPassword = !showPassword"
                    :type="showPassword ? 'text' : 'password'" required outlined dense class="mb-2"
                    @input="checkPasswordStrength" @blur="$v.password.$touch()" :loading="loading"
                    autocomplete="new-password">
                    <!-- شريط قوة كلمة المرور -->
                    <template v-slot:progress>
                      <v-progress-linear v-if="password.length > 0" :value="passwordStrengthScore * 25"
                        :color="passwordStrengthColor" height="3" striped></v-progress-linear>
                    </template>
                  </v-text-field>

                  <!-- تأكيد كلمة المرور -->
                  <v-text-field v-model="confirmPassword" :label="$t('signup.confirmPassword')"
                    :rules="confirmPasswordRules" :error-messages="confirmPasswordErrors" name="confirmPassword"
                    prepend-inner-icon="mdi-lock-check" :append-icon="showConfirmPassword ? 'mdi-eye-off' : 'mdi-eye'"
                    @click:append="showConfirmPassword = !showConfirmPassword"
                    :type="showConfirmPassword ? 'text' : 'password'" required outlined dense class="mb-2"
                    @blur="$v.confirmPassword.$touch()" @input="$v.confirmPassword.$touch()" :loading="loading"
                    autocomplete="new-password"></v-text-field>

                  <!-- اختيار الجنس -->
                  <v-row class="mb-2">
                    <v-col cols="12">
                      <v-label class="mb-2">{{ $t('signup.gender') }}</v-label>
                      <v-btn-toggle v-model="gender" mandatory group rounded class="gender-toggle">
                        <v-btn v-for="option in genderOptions" :key="option.value" :value="option.value"
                          :class="{ 'active-gender': gender === option.value, 
                          'active-gender-female': (gender === option.value && gender == 'female' ) }" depressed>
                          <v-icon left>{{ option.icon }}</v-icon>
                          {{ $t(`signup.${option.value}`) }}
