                      </v-btn-toggle>
                    </v-col>
                  </v-row>

                  <!-- تاريخ الميلاد (اختياري) -->
                  <v-row class="mb-2">
                    <v-col cols="12">
                      <v-menu ref="birthDateMenu" v-model="birthDateMenu" :close-on-content-click="false"
                        transition="scale-transition" offset-y min-width="auto">
                        <template v-slot:activator="{ on, attrs }">
                          <v-text-field v-model="birthDate" :label="$t('signup.birthDate')"
                            prepend-inner-icon="mdi-calendar" readonly v-bind="attrs" v-on="on" outlined dense
                            clearable></v-text-field>
                        </template>
                        <v-date-picker v-model="birthDate" :max="maxDate" @input="birthDateMenu = false"
