                      <v-combobox v-model="hobbies" :label="$t('signup.hobbies')" :items="hobbySuggestions"
                        prepend-inner-icon="mdi-heart" outlined dense chips clearable multiple small-chips></v-combobox>
                    </v-col>
                  </v-row> -->

                  <!-- الشروط والأحكام -->
                  <!-- <v-row class="mb-4">
                    <v-col cols="12">
                      <v-checkbox
                        v-model="agreeTerms"
                        :rules="[v => !!v || $t('signup.termsRequired')]"
                        :label="$t('signup.agreeTerms')"
                        color="primary"
                        hide-details="auto"
                        dense
                      >
                        <template v-slot:label>
                          <span>
                            {{ $t('signup.agreeTerms') }}
                            <router-link to="/terms" class="terms-link">
                              {{ $t('signup.termsOfService') }}
                            </router-link>
                            {{ $t('signup.and') }}
                            <router-link to="/privacy" class="terms-link">
                              {{ $t('signup.privacyPolicy') }}
                            </router-link>
                          </span>
                        </template>
                      </v-checkbox>
                    </v-col>
                  </v-row> -->

                  <!-- زر إنشاء الحساب -->
                  <v-btn block x-large color="primary" @click.prevent="onSignup" :loading="loading" :disabled="disable"
                    class="signup-btn mb-3">
                    <v-icon left v-if="!loading">mdi-account-plus</v-icon>
                    <span v-if="!loading">{{ $t('signup.createAccount') }}</span>
                    <span v-else>{{ $t('signup.creatingAccount') }}sssssss</span>
                  </v-btn>

                  <!-- خيارات التسجيل الاجتماعي -->
                  <v-divider class="my-4">
                    <span class="px-2 grey--text text--lighten-1">
                      {{ $t('signup.or') }}
                    </span>
                  </v-divider>

                  <!-- <v-row no-gutters>
                    <v-col cols="6" class="pr-1">
                      <v-btn
                        block
                        outlined
                        color="blue darken-3"
                        @click="socialSignup('facebook')"
                        :disabled="loading"
                      >
                        <v-icon left>mdi-facebook</v-icon>
                        Facebook
                      </v-btn>
                    </v-col>
                    <v-col cols="6" class="pl-1">
                      <v-btn
                        block
                        outlined
                        color="red darken-3"
                        @click="socialSignup('google')"
                        :disabled="loading"
                      >
                        <v-icon left>mdi-google</v-icon>
                        Google
                      </v-btn>
                    </v-col>
                  </v-row> -->
                </v-form>
              </v-card-text>

              <!-- فاصل -->
              <v-divider></v-divider>

              <!-- تبديل اللغة -->
              <v-card-actions class="pa-4 language-switcher">
                <v-spacer></v-spacer>
                <v-btn-toggle v-model="selectedLanguage" mandatory group borderless rounded class="language-toggle">
                  <v-btn v-for="lang in languages" :key="lang.code" :value="lang.code"
                    @click="changeLanguage(lang.code)" :class="{ 'active-lang': $i18n.locale === lang.code }" small>
                    <country-flag :country="lang.flag" size="small" class="mr-1" />
                    <span class="lang-text">{{ lang.name }}</span>
                  </v-btn>
                </v-btn-toggle>
                <v-spacer></v-spacer>
              </v-card-actions>
            </v-card>

            <!-- حقوق النشر -->
            <div class="text-center mt-4 copyright">
              <span class="white--text text--lighten-2">
                © {{ new Date().getFullYear() }} Glass Book. {{ $t('signup.allRights') }}
              </span>
