          </v-col>
        </v-row>
      </v-container>
    </v-parallax>

    <!-- نافذة تأكيد البريد الإلكتروني -->
    <v-dialog v-model="verificationDialog" max-width="500" persistent>
      <v-card class="verification-card">
        <v-card-title class="dialog-header primary white--text">
