        <v-card-text class="text-center pa-6">
          <v-icon size="80" color="primary" class="mb-4">mdi-email-send</v-icon>
          <h3 class="mb-3">{{ $t('signup.checkEmail') }}</h3>
          <p class="grey--text">
            {{ $t('signup.verificationSent') }} <strong>{{ email }}</strong>
          </p>

          <v-btn color="primary" @click="resendVerification" :loading="resending" :disabled="resendDisabled"
            class="mt-2">
            <v-icon left>mdi-email-sync</v-icon>
            {{ $t('signup.resendEmail') }}
          </v-btn>

          <p v-if="resendTimer > 0" class="caption mt-2">
            {{ $t('signup.resendTimer') }} {{ resendTimer }}s
          </p>
        </v-card-text>

        <v-card-actions class="pa-4">
          <v-spacer></v-spacer>
