<script>
import {
  required,
  email,
  minLength,
  maxLength,
  sameAs,
  alphaNum
} from "vuelidate/lib/validators";
import { mapActions, mapGetters } from "vuex";
import CountryFlag from "vue-country-flag";

export default {
  name: "SignupPage",

  components: {
    CountryFlag
  },

  props: {
    source: String
  },

  data: () => ({
    // نموذج البيانات
    email: "",
    name: "",
    password: "",
    confirmPassword: "",
    gender: "male",
    birthDate: null,
    hobbies: [],

    // حالة الواجهة
    activeTab: 1,
    showPassword: false,
    showConfirmPassword: false,
    formValid: false,
    loading: false,
    resending: false,
    verificationDialog: false,
    birthDateMenu: false,
    agreeTerms: false,

    // اللغات
    selectedLanguage: "en",
    languages: [
      { code: "en", name: "English", flag: "gb" },
      { code: "ar", name: "العربية", flag: "sa" }
    ],

    // خيارات الجنس
    genderOptions: [
      { value: "male", icon: "mdi-gender-male" },
      { value: "female", icon: "mdi-gender-female" }
    ],

    // اقتراحات الهوايات
    hobbySuggestions: [
      "Reading", "Sports", "Music", "Travel", "Gaming",
      "Photography", "Cooking", "Art", "Movies", "Technology"
    ],

    // التبويبات
    tabs: [
      { value: "Login", icon: "mdi-login" },
      { value: "signup", icon: "mdi-account-plus" }
    ],

    // مؤقت إعادة الإرسال
    resendTimer: 0,
    timerInterval: null
  }),

  validations: {
    name: {
      required,
      minLength: minLength(3),
      maxLength: maxLength(20),
      alphaNum
    },
    email: {
      required,
      email
    },
    password: {
      required,
      minLength: minLength(8),
      hasUpperCase: (value) => /[A-Z]/.test(value),
      hasLowerCase: (value) => /[a-z]/.test(value),
      hasNumber: (value) => /[0-9]/.test(value),
      hasSpecialChar: (value) => /[!@#$%^&*(),.?":{}|<>]/.test(value)
    },
    confirmPassword: {
      required,
      same: sameAs("password")
    },
    gender: {
      required
    }
  },

  computed: {
    ...mapGetters({
      isAuthenticated: "auth/isAuthenticated",
      authError: "auth/error",
      authSuccess: "auth/success"
    }),

    errorMessage() {
      return this.authError;
    },

    successMessage() {
      return this.authSuccess;
    },

    // قواعد التحقق للحقول
    nameRules() {
      return [
        v => !!v || this.$t('validation.nameRequired'),
        v => (v && v.length >= 3) || this.$t('validation.nameMinLength'),
        v => (v && v.length <= 20) || this.$t('validation.nameMaxLength'),
        v => /^[a-zA-Z0-9_ ]+$/.test(v) || this.$t('validation.nameAlphaNum')
      ];
    },

    emailRules() {
      return [
        v => !!v || this.$t('validation.emailRequired'),
        v => /.+@.+\..+/.test(v) || this.$t('validation.emailInvalid')
      ];
    },

    passwordRules() {
      return [
        v => !!v || this.$t('validation.passwordRequired'),
        v => (v && v.length >= 8) || this.$t('validation.passwordMinLength'),
        v => /[A-Z]/.test(v) || this.$t('validation.passwordUpperCase'),
        v => /[a-z]/.test(v) || this.$t('validation.passwordLowerCase'),
        v => /[0-9]/.test(v) || this.$t('validation.passwordNumber'),
        v => /[!@#$%^&*(),.?":{}|<>]/.test(v) || this.$t('validation.passwordSpecial')
      ];
    },

    confirmPasswordRules() {
      return [
        v => !!v || this.$t('validation.confirmPasswordRequired'),
        v => v === this.password || this.$t('validation.passwordMatch')
      ];
    },

    // قوة كلمة المرور
    passwordStrengthScore() {
      let score = 0;
      if (!this.password) return 0;
      if (this.password.length >= 8) score++;
      if (/[A-Z]/.test(this.password)) score++;
      if (/[a-z]/.test(this.password)) score++;
      if (/[0-9]/.test(this.password)) score++;
      if (/[!@#$%^&*(),.?":{}|<>]/.test(this.password)) score++;
      return Math.min(score, 4);
    },

    passwordStrength() {
      const score = this.passwordStrengthScore;
      if (score <= 1) return 'weak';
      if (score <= 2) return 'fair';
      if (score <= 3) return 'good';
      return 'strong';
    },

    passwordStrengthColor() {
      const colors = {
        weak: 'error',
        fair: 'warning',
        good: 'info',
        strong: 'success'
      };
      return colors[this.passwordStrength];
    },

    passwordStrengthIcon() {
      const icons = {
        weak: 'mdi-alert-circle',
        fair: 'mdi-alert',
        good: 'mdi-check-circle',
        strong: 'mdi-shield-check'
      };
      return icons[this.passwordStrength];
    },

    // الحد الأقصى للتاريخ
    maxDate() {
      const date = new Date();
      date.setFullYear(date.getFullYear() - 13); // 13 سنة كحد أدنى
      return date.toISOString().split('T')[0];
    },

    // تعطيل الزر
    disable() {
      // return !this.formValid || !this.agreeTerms || this.loading;
      if (
        this.$v.name.required &&
        this.$v.password.required &&
        this.$v.confirmPassword.required &&
        this.$v.confirmPassword.same &&
        this.$v.email.required &&
        this.$v.email.email
      ) {
        return false;
      } else {
        return true;
      }
    },

    nameErrors() {
      const errors = [];
      if (!this.$v.name.$dirty) return errors;
      !this.$v.name.required && errors.push(this.$t('validation.nameRequired'));
      !this.$v.name.minLength && errors.push(this.$t('validation.nameMinLength'));
      !this.$v.name.maxLength && errors.push(this.$t('validation.nameMaxLength'));
      !this.$v.name.alphaNum && errors.push(this.$t('validation.nameAlphaNum'));
      return errors;
    },

    emailErrors() {
      const errors = [];
      if (!this.$v.email.$dirty) return errors;
      !this.$v.email.email && errors.push(this.$t('validation.emailInvalid'));
      !this.$v.email.required && errors.push(this.$t('validation.emailRequired'));
      return errors;
    },

    passwordErrors() {
      const errors = [];
      if (!this.$v.password.$dirty) return errors;
      !this.$v.password.required && errors.push(this.$t('validation.passwordRequired'));
      !this.$v.password.minLength && errors.push(this.$t('validation.passwordMinLength'));
      !this.$v.password.hasUpperCase && errors.push(this.$t('validation.passwordUpperCase'));
      !this.$v.password.hasLowerCase && errors.push(this.$t('validation.passwordLowerCase'));
      !this.$v.password.hasNumber && errors.push(this.$t('validation.passwordNumber'));
      !this.$v.password.hasSpecialChar && errors.push(this.$t('validation.passwordSpecial'));
      return errors;
    },

    confirmPasswordErrors() {
      const errors = [];
      if (!this.$v.confirmPassword.$dirty) return errors;
      !this.$v.confirmPassword.required && errors.push(this.$t('validation.confirmPasswordRequired'));
      !this.$v.confirmPassword.same && errors.push(this.$t('validation.passwordMatch'));
      return errors;
    }
  },

  watch: {
    isAuthenticated(val) {
      if (val) {
        this.$router.push("/posts");
      }
    },

    selectedLanguage(val) {
      localStorage.setItem("locale", val);
    }
  },

  created() {
    // استرجاع اللغة المحفوظة
    const savedLocale = localStorage.getItem("locale") || "en";
    this.selectedLanguage = savedLocale;
    this.$i18n.locale = savedLocale;
  },

  beforeDestroy() {
    if (this.timerInterval) {
      clearInterval(this.timerInterval);
    }
  },

  methods: {
    async onSignup() {
      // منع أي سلوك افتراضي قد يسبب تحديث الصفحة
      event?.preventDefault();
      event?.stopPropagation();

      console.log('signupxxx: ', this.name, this.email, this.password, this.gender);

      // التحقق من صحة البيانات قبل الإرسال
      this.$v.$touch();

      if (this.$v.$invalid) {
        this.$toast?.error(this.$t('signup.formInvalid') || 'Please fix validation errors', {
          position: "top-right",
          duration: 5000
        });
        return;
      }

      // تفعيل حالة التحميل
      this.loading = true;

      setTimeout(async () => {
        try {
          // إرسال البيانات إلى الـ store
          const sifnState = await this.$store.dispatch("signup", {
            name: this.name.trim(),
            email: this.email.toLowerCase().trim(),
            password: this.password,
            gender: this.gender,
            birthDate: this.birthDate,
            hobbies: this.hobbies
          });
          if (sifnState?.success) {
             this.$router.push({ name: "Home" });
           return this.$router.go()
          }
          if (sifnState?.message == "email already exists") {
            this.$notify?.error('email already exists', {
              position: "top-right",
              duration: 5000
            });

            return window.scrollTo({
              top: 0,
              behavior: 'smooth' // تمرير سلس
            });
          }

          // إذا وصلنا إلى هنا، فهذا يعني نجاح العملية
          // لا نحتاج لعمل أي شيء إضافي لأن الـ store سيتعامل مع التوجيه

        } catch (error) {
          // في حالة الفشل، فقط سجل الخطأ وابقَ في نفس الصفحة
          console.error("Signup error caught in component:", error);
          this.$notify?.error('oh error', {
            position: "top-right",
            duration: 5000
          });
          window.scrollTo({
            top: 0,
            behavior: 'smooth' // تمرير سلس
          });
          // رسالة الخطأ ستظهر تلقائياً من Vuex إذا تم ضبطها بشكل صحيح
          // يمكنك إضافة رسالة إضافية إذا أردت

        } finally {
          // تأكد من إيقاف حالة التحميل في كل الأحوال
          this.loading = false;
        }
      }, 2000)
    },
    ...mapActions({
      signupAction: "auth/signup",
      clearAuthMessages: "auth/clearMessages",
      socialLoginAction: "auth/socialLogin",
      resendVerificationAction: "auth/resendVerification"
    }),

    // إنشاء حساب جديد
    // async onSignup() {
    //   this.$v.$touch();

    //   if (this.$v.$invalid) {
    //     this.$toast?.error(this.$t('signup.formInvalid'), {
    //       position: "top-right",
    //       duration: 5000
    //     });
    //     return;
    //   }

    //   this.loading = true;
    //   this.clearAuthMessages();

    //   try {
    //     const userData = {
    //       name: this.name.trim(),
    //       email: this.email.toLowerCase().trim(),
    //       password: this.password,
    //       gender: this.gender,
    //       birthDate: this.birthDate,
    //       hobbies: this.hobbies
    //     };

    //     await this.signupAction(userData);

    //     this.$toast?.success(this.$t('signup.success'), {
    //       position: "top-right",
    //       duration: 5000
    //     });

    //     // إظهار نافذة التحقق من البريد
    //     this.verificationDialog = true;

    //     // بدء مؤقت إعادة الإرسال
    //     this.startResendTimer();

    //   } catch (error) {
    //     console.error("Signup error:", error);
    //     this.$toast?.error(this.$t('signup.error'), {
    //       position: "top-right",
    //       duration: 5000
    //     });
    //   } finally {
    //     this.loading = false;
    //   }
    // },

    // تسجيل الدخول الاجتماعي
    async socialSignup(provider) {
      this.loading = true;
      try {
        await this.socialLoginAction({ provider, mode: 'signup' });
      } catch (error) {
        console.error(`${provider} signup error:`, error);
      } finally {
        this.loading = false;
      }
    },

    // تغيير اللغة
    changeLanguage(locale) {
      this.$i18n.locale = locale;
      this.selectedLanguage = locale;
      localStorage.setItem("locale", locale);

      if (locale === "ar") {
        document.documentElement.setAttribute("dir", "rtl");
        document.body.classList.add("rtl");
      } else {
        document.documentElement.setAttribute("dir", "ltr");
        document.body.classList.remove("rtl");
      }

      this.$toast?.info(this.$t('common.languageChanged'), {
        position: "top-right",
        duration: 2000
      });
    },

    // التحقق من قوة كلمة المرور
    checkPasswordStrength() {
      this.$v.password.$touch();
    },

    // مسح رسائل الخطأ
    clearError() {
      this.clearAuthMessages();
    },

    // مسح رسائل النجاح
    clearSuccess() {
      this.clearAuthMessages();
    },

    // التنقل إلى صفحة تسجيل الدخول
    navigateToLogin() {
      this.$router.push("/login");
    },

    goToLogin() {
      this.verificationDialog = false;
      this.$router.push("/login");
    },

    // إعادة إرسال رمز التحقق
    async resendVerification() {
      if (this.resendTimer > 0) return;

      this.resending = true;
      try {
        await this.resendVerificationAction({ email: this.email });
        this.$toast?.success(this.$t('signup.verificationResent'), {
          position: "top-right",
          duration: 5000
        });
        this.startResendTimer(60);
      } catch (error) {
        console.error("Resend verification error:", error);
      } finally {
        this.resending = false;
      }
    },

    // بدء مؤقت إعادة الإرسال
    startResendTimer(seconds = 60) {
      this.resendTimer = seconds;
      this.timerInterval = setInterval(() => {
        if (this.resendTimer > 0) {
          this.resendTimer--;
        } else {
          clearInterval(this.timerInterval);
        }
      }, 1000);
    }
  }
};
</script>

